public uint ReverseBits(uint n) {
    uint r = 0;
    for (int i = 0; i < 32; i++) {
        r = (r << 1) | (n & 1);   // младший бит n — в младший бит r
        n >>= 1;                  // uint: слева вдвигаются нули
    }
    return r;
}

